import {API_BASE,escapeHTML as esc,sourceURL} from './cuenta/core.js';
const $=s=>document.querySelector(s);let rows=[];
async function load(){try{const res=await fetch(API_BASE+'/api/training',{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!res.ok)throw Error();rows=await res.json();render();}catch{$('#training-cards').replaceChildren();$('#training-status').textContent='No se pudo actualizar la formación. Pulsa Actualizar para reintentar.';}}
function render(){const selected=rows.filter(r=>(!$('#training-area').value||r.categories.includes($('#training-area').value))&&(!$('#training-region').value||r.region===$('#training-region').value)&&(!$('#training-mode').value||r.modes.includes($('#training-mode').value)));$('#training-status').textContent=selected.length+' programas · comprueba la matrícula en cada centro';$('#training-cards').innerHTML=selected.map(r=>`<article class="study"><span class="badge">${r.status==='verified'?'Programa verificado':'Pendiente de revalidación'}</span><h2>${esc(r.title)}</h2><p>${esc(r.org)} · ${esc(r.region)} · ${esc(r.modes.join(' / '))}</p><p>${esc(r.summary)}</p><p><strong>${esc(r.qualification)}</strong></p><p>${esc(r.admission_status)}. ${esc(r.cost)}.</p><p>Comprobación: ${esc(r.last_checked_at.slice(0,10))}</p><a href="${esc(sourceURL(r.source))}" target="_blank" rel="noopener noreferrer">Programa y admisión ↗</a></article>`).join('')||'<p>No hay programas con estos filtros.</p>';}
['Tatuaje','Peluquería','Estilismo/Moda','Maquillaje','Estética','Artesanía','Joyería'].forEach(c=>$('#training-area').add(new Option(c,c)));
['area','region','mode'].forEach(id=>$('#training-'+id).onchange=render);$('#training-retry').onclick=load;load();
